/* Static 7.5.19 compatibility renderer for the owner-requested first-screen
   invoice story. It runs AFTER pinned Next.js hydration; it never edits
   React-owned nodes, RSC payloads, recorded evidence or approval controls.
   Remove when an accepted native source build replaces this baseline. */
(()=>{"use strict";const markup="<header><p class=\"gac-icase-eyebrow\">THE ACTUAL USE CASE · AT A GLANCE</p><h2 id=\"gac-invoice-public-flow-title\">An invoice arrives. What happens before a human decides?</h2><p>The system supports <strong>supplier-invoice and contract verification</strong>. It collects records, checks exact facts in code, compares disputed charges with independent evidence and invokes AI only where unresolved questions justify it. <strong>AI does not autonomously approve payments.</strong></p></header>\n<div class=\"gac-icase-rail\"><div><small>INPUT</small><strong>Invoice + supporting documents</strong></div><span aria-hidden=\"true\">→</span><div><small>GOVERNED CHECKS</small><strong>Rules → evidence → optional AI</strong></div><span aria-hidden=\"true\">→</span><div><small>OUTPUT</small><strong>Review package → human decision</strong></div></div>\n<ol class=\"gac-icase-steps\"><li><div class=\"gac-icase-cardmeta\"><span>01 / 06</span><span>COLLECT</span></div><h3>Request and receive documents</h3><p>Supplier invoice workbook, service records and supporting material enter a versioned case.</p><div class=\"gac-icase-cardfoot\"><span><b>Responsibility:</b> Supplier / operations</span><span><b>Output:</b> Invoice + evidence references</span></div></li><li><div class=\"gac-icase-cardmeta\"><span>02 / 06</span><span>VALIDATE INPUT</span></div><h3>Structure the submission</h3><p>Typed field and completeness checks establish what was received, without treating external prose as commands.</p><div class=\"gac-icase-cardfoot\"><span><b>Responsibility:</b> Deterministic</span><span><b>Output:</b> Validated submission</span></div></li><li><div class=\"gac-icase-cardmeta\"><span>03 / 06</span><span>TIER 1</span></div><h3>Calculate exact facts</h3><p>Code recalculates invoice quantities, rates and totals using reproducible rules. No generative AI needed.</p><div class=\"gac-icase-cardfoot\"><span><b>Responsibility:</b> Deterministic</span><span><b>Output:</b> Arithmetic findings</span></div></li><li><div class=\"gac-icase-cardmeta\"><span>04 / 06</span><span>TIER 2</span></div><h3>Cross-check approved evidence</h3><p>Compare claims against signed contracts and current rate cards; a bounded AI selector may choose Python checks, but checks produce the result.</p><div class=\"gac-icase-cardfoot\"><span><b>Responsibility:</b> Independent evidence</span><span><b>Output:</b> Source-linked discrepancies</span></div></li><li><div class=\"gac-icase-cardmeta\"><span>05 / 06</span><span>TIER 3 · CONDITIONAL</span></div><h3>Reason about unresolved exceptions</h3><p>Only material, unresolved disputes need optional AI Proponent/Opponent, verification and Judge reasoning. All model claims are advisory.</p><div class=\"gac-icase-cardfoot\"><span><b>Responsibility:</b> Optional agentic AI</span><span><b>Output:</b> Exception review package</span></div></li><li><div class=\"gac-icase-cardmeta\"><span>06 / 06</span><span>HUMAN GATE</span></div><h3>Make an accountable decision</h3><p>A named reviewer accepts, rejects or requests correction, while trace and evidence references remain available.</p><div class=\"gac-icase-cardfoot\"><span><b>Responsibility:</b> Human reviewer</span><span><b>Output:</b> Authorized disposition</span></div></li></ol>\n<div class=\"gac-icase-boundaries\"><p><strong>Authority boundary:</strong> Neither a passing automated check nor an AI Judge can approve payment. A human reviewer retains the decision.</p><p><strong>Evidence boundary:</strong> The supplier's assertion is not an approved contractual rate. Check a source's version, validity and provenance first.</p></div>\n<p class=\"gac-icase-links\">A conceptual overview, not proof that every production integration is available or that savings have been measured. <a href=\"/context-engineering/\">How evidence is selected</a> · <a href=\"/use-case-assessment/\">Why this AI use case is justified</a> · <a href=\"/architecture/\">Full architecture</a>.</p>";
const key="gac-invoice-public-flow-20261118";
let queued=false;
function render(){
 const title=document.getElementById("introduction-title");
 if(!title || !document.querySelector("main#main-content"))return;
 const parent=title.closest(".space-y-12");
 if(!parent || document.getElementById(key))return;
 const section=document.createElement("section");section.id=key;
 section.setAttribute("aria-labelledby","gac-invoice-public-flow-title");
 section.innerHTML=markup;
 const grid=title.closest(".grid");
 if(grid && grid.parentElement===parent)grid.insertAdjacentElement("afterend",section);
 else parent.prepend(section);
}
function schedule(){
 if(queued)return;queued=true;
 requestAnimationFrame(()=>{queued=false;render();});
}
function ready(){setTimeout(()=>{render();const main=document.querySelector("main#main-content");if(main){const mo=new MutationObserver(()=>schedule());mo.observe(main,{childList:true,subtree:true});}},1100);}
if(document.readyState==="complete")ready();else window.addEventListener("load",ready,{once:true});
window.addEventListener("popstate",schedule);window.addEventListener("pageshow",schedule);
})();